// Exact compressed solver for odd-perfect (18,0), K=21, kp=15,kc=6.
// sum p=9 forces exactly three negative signs on the 15-point p support.
// Fixing a signed c pattern turns the periodic cross equations into
//   sum_{j in negative triple} column_j = baseline/2.
// A deterministic 64-bit pair-sum hash finds all triples; every hash hit is
// rechecked in all 13 original integer equations, so collisions cannot create
// false exclusions or false witnesses. c->-c is quotiented by fixing the first
// c-support sign positive; PAF/cross feasibility is invariant under that flip.
#include <bits/stdc++.h>
#include <omp.h>
using namespace std;using U=uint32_t;static const U ALL=(1u<<25)-1;static const int N=25;using A=array<int8_t,25>;
U rot(U x,int k){k%=25;return((x<<k)|(x>>(25-k)))&ALL;}U star(U x){U y=0;for(int i=0;i<25;i++)if(x>>i&1)y|=1u<<((25-i)%25);return y;}U mul(U a,U b){U y=0;for(int i=0;i<25;i++)if(a>>i&1)y^=rot(b,i);return y;}
vector<int>units(){vector<int>u;for(int a=1;a<25;a++)if(gcd(a,25)==1)u.push_back(a);return u;}U aff(U x,int a,int b){U y=0;for(int i=0;i<25;i++)if(x>>i&1)y|=1u<<((a*i+b)%25);return y;}
vector<U>orbit_reps(int w){vector<U>reps;unordered_set<U>seen;auto us=units();seen.reserve(5000000);U x=(1u<<w)-1;while(x<(1u<<25)){if(!seen.count(x)){reps.push_back(x);for(int a:us)for(int b=0;b<25;b++)seen.insert(aff(x,a,b));}U c=x&-x,r=x+c;if(!r||r>=(1u<<25))break;x=(((r^x)>>2)/c)|r;}return reps;}
struct Ker{vector<U>b;};Ker kernel(U D){U rows[25]{},Ds=star(D);for(int j=0;j<25;j++){U col=mul(1u<<j,Ds)^mul(D,star(1u<<j));for(int r=0;r<25;r++)if(col>>r&1)rows[r]|=1u<<j;}int pr=0;vector<int>pc;for(int c=0;c<25&&pr<25;c++){int q=-1;for(int r=pr;r<25;r++)if(rows[r]>>c&1){q=r;break;}if(q<0)continue;swap(rows[pr],rows[q]);for(int r=0;r<25;r++)if(r!=pr&&(rows[r]>>c&1))rows[r]^=rows[pr];pc.push_back(c);pr++;}bool isp[25]{};for(int c:pc)isp[c]=1;Ker K;for(int f=0;f<25;f++)if(!isp[f]){U v=1u<<f;for(int r=0;r<pr;r++)if(rows[r]>>f&1)v|=1u<<pc[r];K.b.push_back(v);}return K;}
vector<pair<int,int>>stabilizer(U E){vector<pair<int,int>>s;auto us=units();for(int a:us)for(int b=0;b<25;b++)if(aff(E,a,b)==E)s.push_back({a,b});return s;}U canon_stab(U P,const vector<pair<int,int>>&st){U z=P;for(auto[a,b]:st)z=min(z,aff(P,a,b));return z;}
int qminG(const A&p,const A&c){int q=0;for(int r=1;r<=12;r++){int g=0;for(int i=0;i<25;i++)g+=p[i]*p[(i+r)%25]+c[i]*c[(i+r)%25];q+=(g*g+(abs(g)&1))/2;}return q;}
static const uint64_t R[13]={0x9e3779b97f4a7c15ULL,0xbf58476d1ce4e5b9ULL,0x94d049bb133111ebULL,0xd6e8feb86659fd93ULL,0xa5a3564e27f88683ULL,0x8cb92baa3f3d8dd7ULL,0xdb4f0b9175ae2165ULL,0xbb67ae8584caa73bULL,0x3c6ef372fe94f82bULL,0xa54ff53a5f1d36f1ULL,0x510e527fade682d1ULL,0x1f83d9abfb41bd6bULL,0x5be0cd19137e2179ULL};
uint64_t hv(const array<int,13>&v){uint64_t h=0;for(int r=0;r<13;r++)h+=(uint64_t)(int64_t)v[r]*R[r];return h;}struct Pair{uint8_t i,j;};bool exact3(const array<array<int,13>,15>&col,int i,int j,int k,const array<int,13>&tar){for(int r=0;r<13;r++)if(col[i][r]+col[j][r]+col[k][r]!=tar[r])return false;return true;}
int main(int argc,char**argv){if(argc<2)return 2;int t=atoi(argv[1]);if(t<0||t>6||(t&1))return 2;int w=21-2*t,ew=min(w,25-w);bool comp=w>12;auto Es=orbit_reps(ew);atomic<long long>supp{0},cpat{0},evenbase{0},triples{0},spectral{0};mutex om;vector<pair<A,A>>hits;
#pragma omp parallel for schedule(dynamic,1)
for(int ei=0;ei<(int)Es.size();ei++){U E=Es[ei],D=comp?(ALL^E):E;auto K=kernel(E);auto st=stabilizer(E);uint64_t M=1ULL<<K.b.size();long long ls=0,lc=0,le=0,lt=0,lsp=0;vector<pair<A,A>>local;for(uint64_t m=0;m<M;m++){U P=0;for(int j=0;j<(int)K.b.size();j++)if(m>>j&1)P^=K.b[j];if(__builtin_popcount(P)!=15)continue;U C=P^D;if(__builtin_popcount(C)!=6||canon_stab(P,st)!=P)continue;ls++;vector<int>pi,ci;for(int i=0;i<25;i++){if(P>>i&1)pi.push_back(i);if(C>>i&1)ci.push_back(i);}for(int a=1;a<6;a++)for(int b=a+1;b<6;b++){lc++;A c{};for(int pos:ci)c[pos]=-1;c[ci[0]]=c[ci[a]]=c[ci[b]]=1;array<array<int,13>,15>col{};array<int,13>B{},tar{};bool ok=true;for(int j=0;j<15;j++){int pos=pi[j];for(int r=0;r<13;r++){int z=c[(pos-r+25)%25]+c[(pos+r)%25];col[j][r]=z;B[r]+=z;}}for(int r=0;r<13;r++){if(B[r]&1){ok=false;break;}tar[r]=B[r]/2;}if(!ok)continue;le++;unordered_multimap<uint64_t,Pair>mp;mp.reserve(256);array<uint64_t,15>ch{};for(int j=0;j<15;j++)ch[j]=hv(col[j]);for(int i=0;i<15;i++)for(int j=i+1;j<15;j++)mp.emplace(ch[i]+ch[j],Pair{(uint8_t)i,(uint8_t)j});uint64_t th=hv(tar);for(int k=0;k<15;k++){auto range=mp.equal_range(th-ch[k]);for(auto it=range.first;it!=range.second;++it){int i=it->second.i,j=it->second.j;if(j>=k||!exact3(col,i,j,k,tar))continue;lt++;A p{};for(int pos:pi)p[pos]=1;p[pi[i]]=p[pi[j]]=p[pi[k]]=-1;if(qminG(p,c)<=57){lsp++;local.push_back({p,c});}}}}}supp+=ls;cpat+=lc;evenbase+=le;triples+=lt;spectral+=lsp;if(!local.empty()){lock_guard<mutex>g(om);hits.insert(hits.end(),local.begin(),local.end());}}
cout<<"K21_KP15_TRIPLE t="<<t<<" diff_orbits="<<Es.size()<<" support_orbits="<<supp<<" cpatterns="<<cpat<<" evenbase="<<evenbase<<" exact_pairs="<<triples<<" spectral="<<spectral<<"\n";for(auto&z:hits){cout<<"HIT p=";for(int i=0;i<25;i++)cout<<(int)z.first[i]<<(i==24?'|':',');cout<<"c=";for(int i=0;i<25;i++)cout<<(int)z.second[i]<<(i==24?'\n':',');}}
